#include "stage2_fixture.hpp"
namespace zkgpt::r7::stage2 {
Bytes encodePrivateFixture(const PrivateFixture&f){Writer w;w.text("R7-S2-PRIVATE-FIXTURE-v2");for(auto*r:{&f.primary,&f.alternate,&f.bad_tail}){auto b=encodeRegistry(*r);w.number(b.size());w.raw(b);}for(auto*s:{&f.weight,&f.alternate_weight,&f.bad_tail_weight}){w.number(s->values.size());for(auto&v:s->values)w.scalar(v);w.number(s->blinds.size());for(auto&v:s->blinds)w.scalar(v);}w.number(f.activation.size());for(auto&v:f.activation)w.scalar(v);w.scalar(f.output);return w.b;}
PrivateFixture decodePrivateFixture(const Bytes&b){Reader r{b};need(r.text()=="R7-S2-PRIVATE-FIXTURE-v2","S2 private fixture version");PrivateFixture f;f.primary=decodeRegistry(r.raw(r.number()));f.alternate=decodeRegistry(r.raw(r.number()));f.bad_tail=decodeRegistry(r.raw(r.number()));f.weight.public_pc=f.primary.pc;f.alternate_weight.public_pc=f.alternate.pc;f.bad_tail_weight.public_pc=f.bad_tail.pc;for(auto*s:{&f.weight,&f.alternate_weight,&f.bad_tail_weight}){need(r.number()==1024,"S2 private weight length");for(unsigned i=0;i<1024;++i)s->values.push_back(r.scalar());need(r.number()==32,"S2 private row blinds length");for(unsigned i=0;i<32;++i)s->blinds.push_back(r.scalar());}need(r.number()==1024,"S2 private activation length");for(unsigned i=0;i<1024;++i)f.activation.push_back(r.scalar());f.output=r.scalar();r.end();return f;}
}
